# pfxtev: each rule of src/quest/combat/pfxtev.cpp and the id table of pfxtev.h removed or bent once; src/quest/tests/pfxtev_test.cpp must fail on every one.
# Sourced by ../mutants.sh, which defines `runm <name> <file> <sed> [<build dir> <test target>]`. Run: src/quest/combat/mutants.sh pfxtev
#
# Not listed: `%016llx` to `%llx` or `%08llx` in the decision line's id. Every one of the six ids has a non-zero top nibble, so all three print the same 16
# digits; no id the function accepts can tell them apart.
F=src/quest/combat/pfxtev.cpp
H=src/quest/combat/pfxtev.h
# the six ids: each is the hash of its effect's name (the test compares the table with the hashes), and the count is the table's
runm tev_id0_bit            $H "s/0x3db472928b4d7c45ull/0x3db472928b4d7c44ull/"
runm tev_id1_bit            $H "s/0x75db6596e0af110dull/0x75db6596e0af110cull/"
runm tev_id2_bit            $H "s/0x76db6596e0af110dull/0x76db6596e0af110cull/"
runm tev_id3_bit            $H "s/0x83976b2ec1de4a57ull/0x83976b2ec1de4a56ull/"
runm tev_id4_bit            $H "s/0xb9e607923cff12f3ull/0xb9e607923cff12f2ull/"
runm tev_id5_bit            $H "s/0xbae607923cff12f3ull/0xbae607923cff12f2ull/"
runm tev_id_dropped         $H "s/    0x83976b2ec1de4a57ull, 0xb9e607923cff12f3ull, 0xbae607923cff12f3ull,/    0x83976b2ec1de4a57ull, 0xb9e607923cff12f3ull,/"
# which ids the decision is for
runm tev_scan_skips_last    $F "s/  for (std::size_t i = 0; i < kIdCount; ++i) {/  for (std::size_t i = 0; i + 1 < kIdCount; ++i) {/"
runm tev_scan_skips_first   $F "s/  for (std::size_t i = 0; i < kIdCount; ++i) {/  for (std::size_t i = 1; i < kIdCount; ++i) {/"
runm tev_scan_not_equal     $F "s/    if (kIds\[i\] == id) return true;/    if (kIds[i] != id) return true;/"
runm tev_scan_hit_false     $F "s/    if (kIds\[i\] == id) return true;/    if (kIds[i] == id) return false;/"
runm tev_scan_miss_true     $F "s/^  return false;\$/  return true;/"
runm tev_nonevent_refused   $F "s/  if (!IsEventId(id)) return true;/  if (!IsEventId(id)) return false;/"
runm tev_nonevent_gated     $F "s/  if (!IsEventId(id)) return true;/  if (!IsEventId(id) \&\& false) return true;/"
# the decision: the switch and a combat map, both
runm tev_switch_ignored     $F "s/  const bool switchOn = g_on.load(std::memory_order_relaxed);/  const bool switchOn = true;/"
runm tev_allowed_or         $F "s/  const bool allowed = switchOn \&\& inCombatMap;/  const bool allowed = switchOn || inCombatMap;/"
runm tev_allowed_no_level   $F "s/  const bool allowed = switchOn \&\& inCombatMap;/  const bool allowed = switchOn;/"
runm tev_allowed_no_switch  $F "s/  const bool allowed = switchOn \&\& inCombatMap;/  const bool allowed = inCombatMap;/"
runm tev_allowed_inverted   $F "s/  const bool allowed = switchOn \&\& inCombatMap;/  const bool allowed = !(switchOn \&\& inCombatMap);/"
runm tev_level_arg_true     $F "s/^bool AllowsIn(std::uint64_t id, bool inCombatMap) noexcept { return Decide(id, inCombatMap); }/bool AllowsIn(std::uint64_t id, bool inCombatMap) noexcept { (void)inCombatMap; return Decide(id, true); }/"
runm tev_allows_const       $F "s/^bool AllowsIn(std::uint64_t id, bool inCombatMap) noexcept { return Decide(id, inCombatMap); }/bool AllowsIn(std::uint64_t id, bool inCombatMap) noexcept { return Decide(id, inCombatMap) || true; }/"
# the counters
runm tev_counts_swapped     $F "s/  (allowed ? g_allowed : g_refused).fetch_add(1, std::memory_order_relaxed);/  (allowed ? g_refused : g_allowed).fetch_add(1, std::memory_order_relaxed);/"
runm tev_counts_none        $F "s/  (allowed ? g_allowed : g_refused).fetch_add(1, std::memory_order_relaxed);/  (void)allowed;/"
runm tev_stats_swapped      $F "s/Stats{g_allowed.load(std::memory_order_relaxed), g_refused.load(std::memory_order_relaxed)}/Stats{g_refused.load(std::memory_order_relaxed), g_allowed.load(std::memory_order_relaxed)}/"
# the 64-line cap: 64 decision lines, then one Warning at the 65th decision, then the rest only counted (and still answered)
runm tev_cap_65             $F "s/constexpr std::uint32_t kLogCap = 64;/constexpr std::uint32_t kLogCap = 65;/"
runm tev_cap_63             $F "s/constexpr std::uint32_t kLogCap = 64;/constexpr std::uint32_t kLogCap = 63;/"
runm tev_lines_uncounted    $F "s/g_lines.fetch_add(1, std::memory_order_relaxed) + 1;/g_lines.fetch_add(0, std::memory_order_relaxed) + 1;/"
runm tev_warn_early         $F "s/  if (n == kLogCap + 1) {/  if (n == kLogCap) {/"
runm tev_warn_late          $F "s/  if (n == kLogCap + 1) {/  if (n == kLogCap + 2) {/"
runm tev_warn_every         $F "s/  if (n == kLogCap + 1) {/  if (n >= kLogCap + 1) {/"
runm tev_warn_never         $F "s/  if (n == kLogCap + 1) {/  if (false) {/"
runm tev_warn_level         $F "s/sentinel::LogLevel::kWarn, \"combat_pfxtev_log_cap\"/sentinel::LogLevel::kInfo, \"combat_pfxtev_log_cap\"/"
runm tev_warn_cap_field     $F "s/{{\"cap\", static_cast<long long>(kLogCap)},/{{\"cap\", static_cast<long long>(kLogCap) + 1},/"
runm tev_warn_msg           $F "s/further event-id decisions are counted but not written/further event-id decisions are written/"
runm tev_line_at_cap        $F "s/  if (n > kLogCap) return allowed;/  if (n >= kLogCap) return allowed;/"
runm tev_line_past_cap      $F "s/  if (n > kLogCap) return allowed;/  if (n > kLogCap + 1) return allowed;/"
runm tev_past_cap_true      $F "s/  if (n > kLogCap) return allowed;/  if (n > kLogCap) return true;/"
runm tev_past_cap_inverted  $F "s/  if (n > kLogCap) return allowed;/  if (n > kLogCap) return !allowed;/"
# the decision line
runm tev_line_level         $F "s/sentinel::LogLevel::kInfo, \"combat_pfxtev_decision\"/sentinel::LogLevel::kDebug, \"combat_pfxtev_decision\"/"
runm tev_line_id_upper      $F "s/\"%016llx\"/\"%016llX\"/"
runm tev_line_id_shifted    $F "s/static_cast<unsigned long long>(id));/static_cast<unsigned long long>(id >> 4));/"
runm tev_line_id_const        $F "s/{{\"id\", hex},/{{\"id\", \"0\"},/"
runm tev_line_result        $F "s/{\"result\", allowed ? \"allowed\" : \"refused\"},/{\"result\", allowed ? \"refused\" : \"allowed\"},/"
runm tev_line_reason_switch $F "s/{\"reason\", !switchOn ? \"switch\" : (inCombatMap ? \"switch\" : \"level\")},/{\"reason\", !switchOn ? \"level\" : (inCombatMap ? \"switch\" : \"level\")},/"
runm tev_line_reason_map    $F "s/{\"reason\", !switchOn ? \"switch\" : (inCombatMap ? \"switch\" : \"level\")},/{\"reason\", !switchOn ? \"switch\" : (inCombatMap ? \"level\" : \"switch\")},/"
runm tev_line_reason_first  $F "s/{\"reason\", !switchOn ? \"switch\" : (inCombatMap ? \"switch\" : \"level\")},/{\"reason\", switchOn ? \"switch\" : (inCombatMap ? \"switch\" : \"level\")},/"
runm tev_line_reason_level  $F "s/{\"reason\", !switchOn ? \"switch\" : (inCombatMap ? \"switch\" : \"level\")},/{\"reason\", !switchOn ? \"switch\" : \"switch\"},/"
runm tev_line_msg_allowed   $F "s/{\"msg\", allowed ? \"the renderer may create this event effect\"/{\"msg\", !allowed ? \"the renderer may create this event effect\"/"
# the install: the stored switch, the line, the kill file, the result
runm tev_install_stores_on  $F "s/  g_on.store(configOn, std::memory_order_relaxed);/  g_on.store(true, std::memory_order_relaxed);/"
runm tev_install_stores_off $F "s/  g_on.store(configOn, std::memory_order_relaxed);/  g_on.store(false, std::memory_order_relaxed);/"
runm tev_install_no_store   $F "s/  g_on.store(configOn, std::memory_order_relaxed);/  (void)configOn;/"
runm tev_install_level      $F "s/sentinel::LogLevel::kInfo, \"combat_pfxtev_install\"/sentinel::LogLevel::kDebug, \"combat_pfxtev_install\"/"
runm tev_install_state      $F "s/{{\"state\", configOn ? \"on\" : \"off\"},/{{\"state\", configOn ? \"off\" : \"on\"},/"
runm tev_install_reason     $F "s/{\"reason\", configOn ? \"default\" : \"off_config\"},/{\"reason\", configOn ? \"off_config\" : \"default\"},/"
runm tev_install_switch     $F "s/{\"switch\", \"combat.pfxtev\"},/{\"switch\", \"combat.pfx\"},/"
runm tev_install_msg        $F "s/{\"msg\", configOn ? \"event-effect ids may be created in combat maps;/{\"msg\", !configOn ? \"event-effect ids may be created in combat maps;/"
runm tev_legacy_file        $F "s/legacy::Present(\"pfxtev.off\")/legacy::Present(\"pfxtev.on\")/"
runm tev_legacy_always      $F "s/  if (legacy::Present(\"pfxtev.off\")) {/  if (true) {/"
runm tev_legacy_never       $F "s/  if (legacy::Present(\"pfxtev.off\")) {/  if (false) {/"
runm tev_legacy_level       $F "s/sentinel::LogLevel::kWarn, \"combat_pfxtev_legacy_switch\"/sentinel::LogLevel::kInfo, \"combat_pfxtev_legacy_switch\"/"
runm tev_legacy_file_field  $F "s/{{\"file\", \"pfxtev.off\"},/{{\"file\", \"pfx.off\"},/"
runm tev_legacy_replaced    $F "s/{\"replaced_by\", \"combat.pfxtev: false\"},/{\"replaced_by\", \"combat.pfxtev: true\"},/"
runm tev_legacy_msg         $F "s/the plugin's kill file is no longer read and changes nothing;/the plugin's kill file turns the switch off;/"
runm tev_legacy_turns_off   $F "s/  if (legacy::Present(\"pfxtev.off\")) {/&\n    g_on.store(false, std::memory_order_relaxed);/"
runm tev_result_ok          $F "s/  return {configOn, configOn ? \"installed\" : \"off_config\"};/  return {true, configOn ? \"installed\" : \"off_config\"};/"
runm tev_result_off         $F "s/  return {configOn, configOn ? \"installed\" : \"off_config\"};/  return {false, configOn ? \"installed\" : \"off_config\"};/"
runm tev_result_on_word     $F "s/configOn ? \"installed\" : \"off_config\"};/configOn ? \"on\" : \"off_config\"};/"
runm tev_result_off_word    $F "s/configOn ? \"installed\" : \"off_config\"};/configOn ? \"installed\" : \"off\"};/"
# the switch is on until the install says otherwise (a decision taken before Install, in a fresh process)
runm tev_initial_off        $F "s/std::atomic<bool> g_on{true};/std::atomic<bool> g_on{false};/"
# test support the tests rely on
runm tev_reset_on_off       $F "s/^  g_on.store(true, std::memory_order_relaxed);\$/  g_on.store(false, std::memory_order_relaxed);/"
runm tev_reset_lines_kept   $F "s/^  g_lines.store(0, std::memory_order_relaxed);\$/  (void)0;/"
runm tev_reset_allowed_kept $F "s/^  g_allowed.store(0, std::memory_order_relaxed);\$/  (void)0;/"
runm tev_reset_refused_kept $F "s/^  g_refused.store(0, std::memory_order_relaxed);\$/  (void)0;/"
runm tev_legacy_dir_noop    $F "s/void SetLegacyDirForTest(const char\* dir) noexcept { legacy::SetDirectoryForTest(dir); }/void SetLegacyDirForTest(const char* dir) noexcept { (void)dir; }/"
